.workspace .heard-line .quote-word { font-weight: 600; }
.workspace .entry-word-part { display: flex; flex-direction: column; gap: 4px; }
.workspace .entry-head { display: flex; flex-direction: column; gap: 6px; }
.workspace .entry-word { margin: 0px; font: 500 clamp(30px, 9vw, 40px) / 1.15 "Source Serif 4", Georgia, serif; letter-spacing: -0.01em; color: var(--ink); }
.workspace .entry-say { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 8px; font-size: 13px; color: var(--sub); }
.workspace .entry-ipa { font-size: 14px; color: var(--ink2); }
.workspace .entry-play { width: 26px; height: 26px; display: grid; place-items: center; border-radius: 50%; background: var(--soft); color: var(--ink); transition: background 0.15s; }
.workspace .entry-play.snap-hover { background: var(--soft-hover); }
.workspace .entry-pos { font-style: italic; }
.workspace .entry-gloss { margin-top: 8px; font: 400 23px / 1.3 "Source Serif 4", Georgia, serif; color: var(--ink); }
.workspace .entry-usually { font-size: 13px; color: var(--sub); }
.workspace .entry-scene { display: flex; flex-direction: column; gap: 8px; }
.workspace .entry-label { display: flex; align-items: center; gap: 8px; margin: 0px; font-size: 12px; font-weight: 600; color: var(--ink); }
.workspace .entry-label::before { content: ""; width: 3px; height: 13px; border-radius: 2px; background: rgb(148, 120, 228); }
.theme-dark .workspace .entry-label::before { background: rgb(171, 149, 242); }
.workspace .entry-meaning { font-size: 15px; line-height: 1.55; color: var(--ink); }
.workspace .entry-notice { font-size: 14px; line-height: 1.55; color: var(--ink2); }
.workspace .entry-tips { padding: 0px; }
.workspace .entry-tips summary { display: flex; align-items: center; justify-content: space-between; padding: 13px 0px; list-style: none; font-size: 13px; font-weight: 600; color: var(--ink); }
.workspace .entry-tips summary::-webkit-details-marker { display: none; }
.workspace .tips-arrow { width: 7px; height: 7px; margin-right: 4px; border-top-color: ; border-top-style: ; border-right-color: ; border-right-style: ; border-bottom-color: ; border-bottom-style: ; border-left-color: ; border-left-style: ; border-image-source: ; border-image-slice: ; border-image-width: ; border-image-outset: ; border-image-repeat: ; border-width: 0px 1.5px 1.5px 0px; transform: translateY(-2px) rotate(45deg); transition: transform 0.25s var(--settle); }
.workspace .tips-body { display: flex; flex-direction: column; gap: 14px; padding-bottom: 16px; }
.workspace .tips-body .part { display: flex; flex-direction: column; gap: 5px; }
.workspace .tips-body .label { margin: 0px; font-size: 12px; font-weight: 600; color: var(--sub); }
.workspace .tips-body p { margin: 0px; font-size: 13px; line-height: 1.5; color: var(--ink2); }
.workspace .tips-body .quote { align-self: flex-start; padding: 4px 10px; border-radius: 8px; border: 1px solid var(--line); background: var(--soft3); font: 400 20px / 1.35 "Source Serif 4", Georgia, serif; color: var(--ink); }
.workspace .entry-actions { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 6px; padding: 12px 0px 14px; }
.workspace .entry-actions .btn.primary { padding: 9px 20px; font-size: 13px; font-weight: 500; }
.segment { display: inline-flex; padding: 2px; border-radius: 999px; background: var(--fill); }
.segment button { padding: 4px 11px; border-radius: 999px; font-size: 12px; color: var(--fg-2); }
.segment button[aria-pressed="true"], .segment button[aria-selected="true"] { background: rgb(99, 99, 102); color: rgb(255, 255, 255); font-weight: 500; }
.duet-swap { display: grid; place-items: center; }
.duet-swap > * { grid-area: 1 / 1; }
.bar-face { width: 36px; height: 36px; border-radius: 11px; display: grid; place-items: center; background: var(--face); box-shadow: rgba(27, 32, 31, 0.12) 0px 0px 0px 1px inset, rgba(27, 32, 31, 0.06) 0px 1px 2px; transition: transform 0.28s var(--settle),
    opacity 0.35s ease; }
.theme-dark .bar-face { box-shadow: rgba(255, 255, 255, 0.1) 0px 0px 0px 1px inset; }
.bar-face .duet-alive { display: block; overflow: visible; }
.bar-duet.snap-hover .bar-face { transform: translateY(-1px) scale(1.06) rotate(-2deg); }
.bar-duet:active .bar-face { transform: scale(0.95); }
.bar-line { position: absolute; left: 50%; bottom: -3px; width: 0px; height: 3px; border-radius: 2px; background: var(--accent); transform: translateX(-50%); transition: width 0.3s var(--settle); }
.workspace .segment { background: var(--seg); padding: 3px; border-radius: 10px; }
.workspace .segment button { color: var(--sub); padding: 6px 11px; border-radius: 8px; }
.workspace .duet-alive { --bg: var(--face); --eye: var(--ink); --mouth: var(--ink2); --g-glow: 0; --g-grain: 0; --g-cloud: 0; --g-body: 1; }
.window-head { app-region: drag; margin-top: -40px; padding-top: 40px; }
.window-head button { app-region: no-drag; }
[data-platform="win32"] .window { padding-top: 12px; }
[data-platform="win32"] .window-head { margin-top: 0px; padding-top: 0px; }
.window-head { display: flex; align-items: center; justify-content: space-between; }
.workspace .window-head .segment { padding: 3px; border-radius: 999px; background: var(--seg); }
.workspace .window-head .segment button { padding: 5px 13px; border-radius: 999px; font-size: 12px; font-weight: 500; color: var(--sub); }
.workspace .window-head .segment button[aria-selected="true"] { background: var(--card); color: var(--ink); box-shadow: rgba(27, 32, 31, 0.1) 0px 1px 2px, rgba(27, 32, 31, 0.06) 0px 0px 0px 1px inset; }
.theme-dark .workspace .window-head .segment button[aria-selected="true"] { background: var(--seg-on); box-shadow: rgba(238, 243, 241, 0.1) 0px 0px 0px 1px inset; }
.workspace .window-head { display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 8px; min-height: 44px; }
.workspace .window-head .segment { justify-self: start; }
.workspace .window-head .bar-duet { grid-column: 2; position: relative; width: 44px; height: 44px; display: grid; place-items: center; border-radius: 14px; app-region: no-drag; }
.duet-alive { --bg: #080d0d; --eye: #edf6f4; --mouth: #c6ddd9; --blush: #ff8fa3; --g-body: 0.84; --g-glow: 0.24; --g-grainc: #0b1716; --g-grain: 0.2; --g-cloud: 0.13; --gc: color-mix(in oklab, var(--eye), var(--tc, #fff) var(--ta, 0%)); display: block; flex: 0 0 auto; overflow: visible; user-select: none; }
.duet-alive[data-theme="light"] { --bg: #f6f7f6; --eye: #17211f; --mouth: #3a4644; --blush: #f07a90; --g-body: 0.86; --g-glow: 0.1; --g-grainc: #ffffff; --g-grain: 0.16; --g-cloud: 0.11; }
.duet-alive .sock, .duet-alive .hand { fill: var(--gc); }
.duet-alive .hand { stroke: var(--bg); stroke-width: 1.4; }
.duet-alive .pupil { fill: var(--bg); }
.duet-alive .mouth { fill: var(--mouth); stroke: var(--mouth); stroke-width: 1.3; stroke-linejoin: round; }
.duet-alive .blush { fill: var(--blush); }
.duet-alive .blush-lines { fill: none; stroke: var(--mouth); stroke-width: 1.1; stroke-linecap: round; }
.duet-alive .brow { fill: none; stroke: var(--gc); stroke-width: 2.6; stroke-linecap: round; stroke-dasharray: 1, 1; }
.duet-alive .z { fill: none; stroke: var(--mouth); stroke-width: 0.9; stroke-linecap: round; stroke-linejoin: round; }
.duet-alive .g-grain { opacity: var(--g-grain); pointer-events: none; }
.duet-alive .g-cloud { opacity: var(--g-cloud); pointer-events: none; }
.duet-alive[data-finish="flat"] .g-grain, .duet-alive[data-finish="flat"] .g-cloud { display: none; }
.duet-alive .g-flood { flood-color: var(--g-grainc); }
.duet-alive .g-glow-flood { flood-color: var(--gc); flood-opacity: calc(var(--g-glow) + var(--g-boost, 0)); }
